-- Wires up the C++ scripts in src/server/scripts/Spells/spell_mage.cpp (spell_mage_frostbolt_icicles,
-- spell_mage_frostfire_bolt_icicles, spell_mage_blizzard_icicles, spell_mage_glacial_spike,
-- spell_mage_flurry). Frostbolt/Frostfire Bolt/Blizzard already carry other, unrelated scripts -
-- spell_script_names supports multiple rows per spell_id (its unique key is (spell_id, ScriptName)),
-- so these add to, rather than replace, whatever's already registered for those three IDs.
DELETE FROM `spell_script_names` WHERE (`spell_id`, `ScriptName`) IN ((116, 'spell_mage_frostbolt_icicles'), (44614, 'spell_mage_frostfire_bolt_icicles'), (10, 'spell_mage_blizzard_icicles'), (200002, 'spell_mage_glacial_spike'), (200004, 'spell_mage_flurry'));
