(116, 'spell_mage_frostbolt_icicles'),
(44614, 'spell_mage_frostfire_bolt_icicles'),
(10, 'spell_mage_blizzard_icicles'),
(200002, 'spell_mage_glacial_spike'),
(200004, 'spell_mage_flurry');

-- Conjure Mana Gem's conjured item (5514, Mana Agate): repointed spellid_2 from the old flat
-- "Replenish Mana" (5405, base_points=389) to the new SPELL_EFFECT_ENERGIZE_PCT spell (200005,
-- 30% of max mana - docs/frost-mage-redesign.md sec 2). Plain UPDATE, not DELETE+INSERT -
-- item_template is on this repo's SQL linter's do-not-delete list (creature/gameobject/item/quest
-- templates - deleting one can orphan a live item), and a single-column UPDATE is the more precise
-- edit anyway. The `spellid_2 = 5405` guard makes it a no-op on a second run. 5405 itself is
-- untouched - it's shared with two unrelated items (36799 "Mana Gem", 9397 "Energy Cloak") that
-- should keep the old flat behavior.
UPDATE `item_template` SET `spellid_2` = 200005 WHERE `entry` = 5514 AND `spellid_2` = 5405;

-- Conjure Refreshment's item (43518, Conjured Mana Pie) is NOT touched here - see mage.csv's
-- notes on why a real "100% of max" implementation needs a small AuraScript (no native
-- percentage-of-max periodic aura type exists in this era's engine), not just a data change.

-- Conjure Food (587) / Conjure Water (5504) retirement in favor of Conjure Refreshment
-- (docs/frost-mage-redesign.md sec 2). The single-rank conversion already purged every superseded
-- rank's trainer_spell row (verified live: only these two survivor IDs still have any); dropping
-- these last two rows makes them fully untrainable. Deliberately not deleting the spell_dbc/item
-- data itself - existing characters who already know them, or anything else that still references
-- the IDs, keep working; they just stop being taught.
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 587), (17, 587), (16, 5504), (17, 5504));

-- Deep Freeze (44572, moved from npc.csv to mage.csv - see its notes there) needs to actually be
-- reachable now that it's leaving the old Talent.dbc row (docs/frost-mage-redesign.md sec 2:
-- "Learn level: 42"). No pre-existing trainer_spell row for it (spell was talent-only before) - the
-- DELETE here is only for idempotency on a second run, same as every other INSERT in this file. Its
-- own numbers (30s cooldown, 5s stun, frozen-only usability) already match the spec as-is; see
-- mage.csv's notes on the two real gaps that remain (both C++, not data).
DELETE FROM `trainer_spell` WHERE (`TrainerId`, `SpellId`) IN ((16, 44572), (17, 44572));
